@pytest.mark.asyncio
async def test_nli_ignores_citation_markers(monkeypatch: pytest.MonkeyPatch) -> None:
    """The answer's ``[n]`` citations are stripped before the entailment check."""
    model = Mock()
    model.predict.return_value = np.array([[0.0, 1.0, 0.0]])
    monkeypatch.setattr(HallucinationCheckerGuardrail, "_ensure", lambda self: model)

    await HallucinationCheckerGuardrail().run(
        "The code is ORCHID [1, 2].", {"retrieval_chunks": [{"text": "The code is ORCHID."}]}
    )

    assert model.predict.call_args.args[0] == [["The code is ORCHID.", "The code is ORCHID ."]]


